Check(layout.Frame.Title=="NPC CLEANUP"&&layout.Back()&&layout.Frame.Title=="NPC MANAGER"&&!layout.Back(),"cleanup confirmation returns to cleanup then manager then main menu");

bool espOn=false,espReady=true;int espToggles=0;
layout.OpenManager();layout.ConfigureEsp(()=>espOn,()=>{espOn=!espOn;++espToggles;return espOn?"ESP enabled":"ESP off";},()=>espReady);
Check(layout.Frame.Entries[0].Key=="npc-esp"&&!layout.Frame.Entries[0].On&&layout.Frame.Entries[0].Available,"Enemy ESP is first in NPC Manager and reflects its existing state");
await layout.ActivateAsync("npc-esp");Check(espOn&&espToggles==1&&layout.Frame.Entries[0].On,"manager ESP toggles the shared control exactly once");
espOn=false;Check(!layout.Frame.Entries[0].On,"manager reads external ESP state changes instead of keeping a separate flag");
espReady=false;await layout.ActivateAsync("npc-esp");Check(espToggles==1&&!layout.Frame.Entries[0].Available,"ESP obeys shared trainer availability");
var distanceSnapshots=new[]{Guard(701,false) with {Distance=30},Guard(702) with {Distance=5},Guard(703,false) with {Distance=5}};
var distanceCalls=new List<uint>();
using var distances=new NpcOverlayMenu(()=>Process.GetCurrentProcess(),_=>Task.FromResult<NpcSnapshot[]?>(distanceSnapshots),(_,act,id,hp,c,a)=>{distanceCalls.Add(id);return Task.FromResult("Requested");});
await distances.RefreshAsync(true);distances.OpenManager();await distances.ActivateAsync("browse");
Check(distances.Frame.Entries.Where(e=>e.Key.StartsWith("npc:")).Select(e=>e.Key).SequenceEqual(new[]{Key(702),Key(703),Key(701)}),"browse sorts nearest first and uses stable ID to break distance ties");
Check(distances.Frame.Entries.First(e=>e.Key==Key(702)).Value!.EndsWith("5.0 m"),"compact NPC rows show distance to Sam in metres");
await distances.ActivateAsync(Key(701));distanceSnapshots[0]=distanceSnapshots[0] with {Distance=1};distanceSnapshots[1]=distanceSnapshots[1] with {Distance=100};await distances.RefreshAsync(true);
await distances.ActivateAsync("health:75");Check(distanceCalls.SequenceEqual(new uint[]{701}),"distance reordering cannot retarget an already selected NPC");distances.Back();
Check(distances.Frame.Entries.First(e=>e.Key.StartsWith("npc:")).Key==Key(701),"live distance refresh reorders the browser");
await distances.ActivateAsync("filter-menu");await distances.ActivateAsync("filter:1");Check(distances.Frame.Entries.Where(e=>e.Key.StartsWith("npc:")).Select(e=>e.Key).SequenceEqual(new[]{Key(701),Key(703)}),"Map filter retains nearest-first ordering");
await distances.ActivateAsync("filter-menu");await distances.ActivateAsync("filter:2");Check(distances.Frame.Entries.Single(e=>e.Key.StartsWith("npc:")).Key==Key(702),"Spawned filter retains its own NPC subset");

var stockText="EQUIPMENT:1\n"+string.Join("\n",Enumerable.Range(1,17).Select(id=>$"{id}|0|0|0"));
Check(EquipmentStock.Parse(stockText).Length==17,"equipment protocol covers all seventeen allowlisted items");
void BadStock(string input,string label){try{EquipmentStock.Parse(input);}catch(FormatException){Console.WriteLine("PASS "+label);return;}throw new Exception(label);}
BadStock(stockText.Replace("17|0|0|0","16|0|0|0"),"duplicate equipment identities rejected");
BadStock(stockText.Replace("17|0|0|0","18|0|0|0"),"unknown equipment identities rejected");
BadStock(stockText.Replace("17|0|0|0","17|2|0|0"),"invalid ownership marker rejected");
BadStock(stockText.Replace("17|0|0|0","17|1|-1|5"),"negative quantities rejected");
InvalidInput(new("Quantity","0",MenuInputKind.Quantity),"zero equipment quantity rejected");
InvalidInput(new("Quantity","1000",MenuInputKind.Quantity),"oversized equipment quantity rejected");
InvalidInput(new("Quantity","2.5",MenuInputKind.Quantity),"fractional equipment quantity rejected");
Check(new OverlayTextEditor("",new("Quantity","999",MenuInputKind.Quantity)).Value()=="999","maximum input quantity accepted for native clamping");
var equipmentStock=EquipmentStock.Parse(stockText);var equipmentCalls=new List<(int Id,int Op,int Count)>();
using var equipment=new EquipmentMenu(()=>Process.GetCurrentProcess(),_=>Task.FromResult<EquipmentStock[]?>(equipmentStock),(_,id,op,quantity)=>{
 equipmentCalls.Add((id,op,quantity));equipmentStock[id-1]=new(id,true,Math.Min(10,op==0?equipmentStock[id-1].Quantity+quantity:quantity),10);return Task.FromResult("Updated");});
await equipment.RefreshAsync(true);equipment.Open();
Check(equipment.Frame.Entries.Count(e=>e.Key.StartsWith("equipment-category:"))==4,"equipment root groups the four requested categories");
await equipment.ActivateAsync("equipment-category:1");Check(equipment.Frame.Entries.Count(e=>e.Key.StartsWith("equipment-item:"))==5,"launcher category contains all five compatible ammunition types");
await equipment.ActivateAsync("equipment-item:3");
Check(!equipment.Frame.Entries.First(e=>e.Key.StartsWith("equipment-select:")).Available,"unowned equipment cannot be selected");
await Reject(()=>equipment.ActivateAsync($"equipment-select:{Environment.ProcessId}:3:0"),"direct select of an unowned item rejected");
await equipment.ActivateAsync($"equipment-add:{Environment.ProcessId}:3:5");
Check(equipmentCalls[^1]==(3,0,5)&&equipment.Frame.Entries.First(e=>e.Key.StartsWith("equipment-select:")).Available,"Give 5 dispatches the exact item and refreshes ownership");
await equipment.ActivateAsync($"equipment-set:{Environment.ProcessId}:3:7");Check(equipmentCalls[^1]==(3,1,7),"Set quantity sends an absolute quantity rather than an increment");
await Reject(()=>equipment.ActivateAsync($"equipment-set:{Environment.ProcessId}:3:1000"),"invalid quantity cannot reach the native helper");
await Reject(()=>equipment.ActivateAsync($"equipment-add:{Environment.ProcessId}:99:1"),"noncatalog item cannot reach the helper");
await Reject(()=>equipment.ActivateAsync($"equipment-add:1:3:1"),"stale game session input cannot give an item to a new session");
Check(!equipment.Busy,"failed equipment action clears its busy state");
equipment.Back();equipment.Back();await equipment.ActivateAsync("equipment-category:0");await equipment.ActivateAsync("equipment-item:1");
Check(!equipment.Frame.Entries.Any(e=>e.Key.StartsWith("equipment-set:"))&&equipment.Frame.Entries.Count(e=>e.Key.StartsWith("equipment-add:"))==1,"weapons offer one grant rather than stack quantity controls");
Check(equipment.Back()&&equipment.Back()&&!equipment.Back(),"equipment Back navigation returns through category to root then main");
var equipmentStarted=new TaskCompletionSource<bool>();var equipmentDone=new TaskCompletionSource<string>();
using var pendingEquipment=new EquipmentMenu(()=>Process.GetCurrentProcess(),_=>Task.FromResult<EquipmentStock[]?>(equipmentStock),async (_,id,op,q)=>{equipmentStarted.TrySetResult(true);var reply=await equipmentDone.Task;equipmentStock[id-1]=equipmentStock[id-1] with {Quantity=equipmentStock[id-1].Quantity+q};return reply;});
await pendingEquipment.RefreshAsync(true);await pendingEquipment.ActivateAsync("equipment-category:1");await pendingEquipment.ActivateAsync("equipment-item:3");
var equipTask=pendingEquipment.ActivateAsync($"equipment-add:{Environment.ProcessId}:3:1");await equipmentStarted.Task;
Check(pendingEquipment.Busy&&pendingEquipment.Back()&&pendingEquipment.Back(),"equipment navigation stays available during a pending mutation");
await pendingEquipment.ActivateAsync("equipment-category:2");await pendingEquipment.ActivateAsync("equipment-item:8");
Check(!pendingEquipment.Frame.Entries.First(e=>e.Key.StartsWith("equipment-add:")).Available,"new equipment mutations stay disabled while a request is pending");
equipmentDone.SetResult("Updated");await equipTask;
Check(!pendingEquipment.Busy&&pendingEquipment.Frame.Title=="WALL MINE","equipment completion preserves the newly browsed item page");

var freezeSnapshots=new List<NpcSnapshot>{Guard(801,false),Guard(802),Guard(803,false) with {ProtectedGlobal=true}};
var freezeCalls=new List<(string Action,uint Id)>();int thawCalls=0,pingCalls=0;bool thawFails=false;
using var freezing=new NpcOverlayMenu(()=>Process.GetCurrentProcess(),_=>Task.FromResult<NpcSnapshot[]?>(freezeSnapshots.ToArray()),(_,act,id,hp,c,a)=>{freezeCalls.Add((act,id));return Task.FromResult("Updated");},freezeControl:(_,restore)=>{
 if(restore){if(thawFails)throw new InvalidOperationException("Request busy");++thawCalls;return Task.FromResult("FROZEN:0");}
 ++pingCalls;return Task.FromResult("FROZEN:2");});
await freezing.RefreshAsync(true);freezing.OpenManager();await freezing.ActivateAsync("global-menu");
Check(!freezing.Frame.Entries.First(e=>e.Key=="global-freeze").On,"global Freeze starts off");
await freezing.ActivateAsync("global-freeze");
Check(freezing.Frame.Entries[0].Key=="global-cancel"&&freezeCalls.Count==0,"freezing requires a Cancel-first captured-target confirmation");
await freezing.ActivateAsync("global-cancel");await freezing.ActivateAsync("global-freeze");
confirm=freezing.Frame.Entries.First(e=>e.Key.StartsWith("global-confirm:")).Key;await freezing.ActivateAsync(confirm);
Check(freezeCalls.SequenceEqual(new[]{("freeze",801u),("freeze",802u)})&&freezing.Frame.Entries.First(e=>e.Key=="global-freeze").On,"freeze includes both origins and excludes protected NPCs");
await freezing.PingFreezeAsync();Check(pingCalls==1,"heartbeat keeps owned freeze active while browsing elsewhere");
await freezing.ActivateAsync("browse");Check(freezing.Frame.Entries.First(e=>e.Key==Key(801)).Value!.StartsWith("Frozen"),"frozen NPC is marked in browse roster");
await freezing.ActivateAsync(Key(801));await Reject(()=>freezing.ActivateAsync("condition:2"),"condition edits cannot interrupt a frozen NPC");
await freezing.ActivateAsync("global-menu");await freezing.ActivateAsync("scope-menu");await freezing.ActivateAsync("scope:1");
thawFails=true;await Reject(()=>freezing.ActivateAsync("global-freeze"),"failed thaw is reported");
Check(freezing.Frame.Entries.First(e=>e.Key=="global-freeze").On&&!freezing.Busy,"failed thaw retains ownership for retry and clears busy state");
thawFails=false;await freezing.ActivateAsync("global-freeze");
Check(thawCalls==1&&!freezing.Frame.Entries.First(e=>e.Key=="global-freeze").On,"unfreeze restores the captured set even after scope changes");
await freezing.ActivateAsync("global-freeze");confirm=freezing.Frame.Entries.First(e=>e.Key.StartsWith("global-confirm:")).Key;freezeCalls.Clear();await freezing.ActivateAsync(confirm);
Check(freezeCalls.SequenceEqual(new[]{("freeze",801u)}),"new freeze capture obeys the selected Map-only scope");
await freezing.RestoreFrozenAsync();Check(thawCalls==2,"shutdown restoration thaws owned NPCs");

var moveSnapshots=new List<NpcSnapshot>{Guard(901,false),Guard(902,false) with {ProtectedGlobal=true,Weapon="None",InstanceName="NamedMissionNPC"},Guard(903),Guard(904,false) with {Health=0,PawnState="s_Dead",AiState="s_Dead"}};
var moveCalls=new List<(uint Id,int Metres,int Slot)>();var unrelatedActions=new List<string>();bool refuseFirstMove=false;
using var moving=new NpcOverlayMenu(()=>Process.GetCurrentProcess(),_=>Task.FromResult<NpcSnapshot[]?>(moveSnapshots.ToArray()),(_,act,id,hp,c,a)=>{unrelatedActions.Add(act);return Task.FromResult("Updated");},frontAction:(_,id,metres,slot)=>{
 if(refuseFirstMove&&id==901)throw new InvalidOperationException("Position blocked");moveCalls.Add((id,metres,slot));return Task.FromResult("Moved");});
await moving.RefreshAsync(true);moving.OpenMapRoster();await moving.ActivateAsync(Key(901));await moving.ActivateAsync("position-menu");
Check(moving.Frame.Entries.First(e=>e.Key=="move-distance-position").Value=="3 m","individual front move defaults to the agreed three metres");
await moving.ActivateAsync("front");Check(moveCalls[^1]==(901u,3,0),"individual front move uses selected NPC and default distance without spawning");
await moving.ActivateAsync("move-distance-position");
Check(moving.Frame.Entries.Where(e=>e.Key.StartsWith("move-distance:")).Select(e=>e.Key).SequenceEqual(new[]{"move-distance:3","move-distance:4","move-distance:5","move-distance:6"}),"distance selector only offers three through six metres");
await Reject(()=>moving.ActivateAsync("move-distance:2"),"closer-than-three-metre distance rejected");
await moving.ActivateAsync("move-distance:6");await moving.ActivateAsync("front");Check(moveCalls[^1]==(901u,6,0),"individual front move forwards chosen six metres");
await moving.ActivateAsync("global-menu");await moving.ActivateAsync("scope-menu");await moving.ActivateAsync("scope:2");
moveCalls.Clear();await moving.ActivateAsync("move-map-all");
Check(moving.Frame.Entries[0].Key=="global-cancel"&&moveCalls.Count==0,"move-all captures map NPCs and defaults to Cancel");
confirm=moving.Frame.Entries.First(e=>e.Key.StartsWith("global-confirm:")).Key;await moving.ActivateAsync(confirm);
Check(moveCalls.SequenceEqual(new[]{(901u,6,0),(902u,6,1)}),"move-all includes existing named and unarmed map NPCs and excludes spawns and dead NPCs regardless of global condition scope");
Check(unrelatedActions.Count==0,"move controls never invoke spawn or condition actions");
await moving.ActivateAsync(Key(902));await moving.ActivateAsync("position-menu");await moving.ActivateAsync("move-exclude");
await moving.ActivateAsync("global-menu");await moving.ActivateAsync("move-map-all");confirm=moving.Frame.Entries.First(e=>e.Key.StartsWith("global-confirm:")).Key;moveCalls.Clear();await moving.ActivateAsync(confirm);
Check(moveCalls.SequenceEqual(new[]{(901u,6,0)}),"mission NPCs can be explicitly excluded from group moves");
await moving.ActivateAsync(Key(902));await moving.ActivateAsync("move-exclude");await moving.ActivateAsync("move-map-all");confirm=moving.Frame.Entries.First(e=>e.Key.StartsWith("global-confirm:")).Key;
refuseFirstMove=true;moveCalls.Clear();summary=await moving.ActivateAsync(confirm);refuseFirstMove=false;
Check(moveCalls.SequenceEqual(new[]{(902u,6,1)})&&summary.Contains("1 requested, 0 skipped, 1 failed")&&summary.Contains("Position blocked"),"one blocked destination does not retarget or abort other map moves");
await moving.ActivateAsync("move-map-all");confirm=moving.Frame.Entries.First(e=>e.Key.StartsWith("global-confirm:")).Key;moveSnapshots.RemoveAll(n=>n.Id==901);moveCalls.Clear();summary=await moving.ActivateAsync(confirm);
Check(moveCalls.SequenceEqual(new[]{(902u,6,1)})&&summary.Contains("1 skipped"),"disappeared captured map NPC is skipped without substituting a different actor");

var failedGrantStock=EquipmentStock.Parse(stockText);
using var missingGrant=new EquipmentMenu(()=>Process.GetCurrentProcess(),_=>Task.FromResult<EquipmentStock[]?>(failedGrantStock),(_,id,op,q)=>Task.FromResult("Success"));
await missingGrant.RefreshAsync(true);await missingGrant.ActivateAsync("equipment-category:2");await missingGrant.ActivateAsync("equipment-item:8");
await Reject(()=>missingGrant.ActivateAsync($"equipment-add:{Environment.ProcessId}:8:1"),"grant success is rejected when the item never reaches Sam's inventory");
Check(!missingGrant.Busy,"failed grant verification clears the pending state");
failedGrantStock[7]=new(8,true,1,3);
await Reject(()=>missingGrant.ActivateAsync($"equipment-add:{Environment.ProcessId}:8:1"),"unchanged quantity cannot be reported as a successful Give");
failedGrantStock[7]=new(8,true,3,3);await missingGrant.RefreshAsync(true);
Check(!missingGrant.Frame.Entries.First(e=>e.Key.StartsWith("equipment-add:")).Available,"full Wall Mine stack disables Give with an explicit game-limit label");
string fullReply=await missingGrant.ActivateAsync($"equipment-add:{Environment.ProcessId}:8:1");Check(fullReply.Contains("game's limit"),"direct Give on a full stack explains why the quantity cannot increase");
var clampedStock=EquipmentStock.Parse(stockText);clampedStock[7]=new(8,true,1,3);
using var clampedGrant=new EquipmentMenu(()=>Process.GetCurrentProcess(),_=>Task.FromResult<EquipmentStock[]?>(clampedStock),(_,id,op,q)=>{clampedStock[id-1]=new(id,true,3,3);return Task.FromResult("Updated");});
await clampedGrant.RefreshAsync(true);await clampedGrant.ActivateAsync("equipment-category:2");await clampedGrant.ActivateAsync("equipment-item:8");
string clampReply=await clampedGrant.ActivateAsync($"equipment-add:{Environment.ProcessId}:8:5");Check(clampReply.Contains("3 / 3 confirmed"),"Give 5 verifies the actual capped three-mine inventory count");

namespace SCTrainer {
 internal sealed record GameMenuEntry(string Label,bool On,bool Available,string Key,string? Value=null,bool Toggle=true,bool Navigation=false,GameMenuInput? Input=null);
 internal sealed record GameMenuFrame(string Key,string Title,GameMenuEntry[] Entries);
 internal static class DirectLevelLoader {
  public static Task<string> MoveNpcFrontAsync(Process game,uint id,int metres,int slot)=>throw new Exception("Unexpected live NPC move");
  public static Task<string> FreezeControlAsync(Process game,bool restore=false)=>throw new Exception("Unexpected live freeze control");
  public static Task<EquipmentStock[]?> ReadEquipmentAsync(Process game)=>throw new Exception("Unexpected real equipment read");
  public static Task<string> EquipmentActionAsync(Process game,int id,int operation,int quantity)=>throw new Exception("Unexpected real equipment mutation");
  public static void ValidateGame(Process game)=>throw new Exception("Unexpected real game validation in test");
  public static Task<NpcSnapshot[]?> ReadNpcsAsync(Process game)=>throw new Exception("Unexpected real read in test");
  public static Task<string> NpcActionAsync(Process game,string action,uint id=0,int hp=100,NpcConditionEdit? condition=null,NpcActivityEdit? activity=null,NpcPosition? position=null,bool waitForCompletion=true)=>throw new Exception("Unexpected real action in test");
 }
}
